useEffect(() => {
  const abortController = new AbortController();
  const roomId = room.id();

  const roomChanged = prevRoomIdRef.current !== roomId;
  const roomInfoChanged = prevRoomInfoRef.current !== roomInfo;
  prevRoomIdRef.current = roomId;
  prevRoomInfoRef.current = roomInfo;

  // Show cached data immediately to avoid blank flash on FlashList recycle
  if (lastMessageCache.has(roomId)) {
