1	import {
2	  Membership,
3	  type RoomInterface,
4	  type RoomListEntriesUpdate,
5	  RoomListEntriesUpdate_Tags,
6	  type RoomListEntriesWithDynamicAdaptersResultInterface,
7	  type RoomListInterface,
8	  RoomListServiceState,
9	  type TaskHandleInterface,
10	} from "@unomed/react-native-matrix-sdk";
11	import { useAtomValue, useSetAtom } from "jotai";
12	import { useEffect, useRef } from "react";
13	import Toast from "react-native-toast-message";
14	import { MatrixJotaiStore } from "../const/matrx-jotai-store";
15	import { MatrixAtoms } from "../jotai";
16	import { MatrixCore } from "../services/MatrixCore";
17	
18	export const RoomListProvider = () => {
19	  const client = useAtomValue(MatrixAtoms.matrixClient);
20	  const syncService = useAtomValue(MatrixAtoms.syncService);
21	  const setIsLoading = useSetAtom(MatrixAtoms.roomListLoading);
22	
23	  // Unfiltered rooms matching the SDK's index space — required for correct diff application
24	  const roomsRef = useRef<RoomInterface[]>([]);
25	  const hasShownInitialSyncToast = useRef(false);
26	
27	  const roomListRef = useRef<RoomListInterface | null>(null);
28	  const entriesResultRef =
29	    useRef<RoomListEntriesWithDynamicAdaptersResultInterface | null>(null);
30	
31	  useEffect(() => {
32	    if (!client || !syncService) return;
33	
34	    let streamHandle: TaskHandleInterface | null = null;
35	    let stateHandle: TaskHandleInterface | null = null;
36	
37	    const applyDiffsAndPublish = (
38	      updates: RoomListEntriesUpdate[],
39	    ): RoomInterface[] => {
40	      const rooms = [...roomsRef.current];
41	
42	      for (const update of updates) {
43	        switch (update.tag) {
44	          case RoomListEntriesUpdate_Tags.Reset:
45	            rooms.splice(0, rooms.length, ...update.inner.values);
46	            break;
47	          case RoomListEntriesUpdate_Tags.Append:
48	            rooms.push(...update.inner.values);
49	            break;
50	          case RoomListEntriesUpdate_Tags.Clear:
51	            rooms.splice(0, rooms.length);
52	            break;
53	          case RoomListEntriesUpdate_Tags.Insert:
54	            rooms.splice(update.inner.index, 0, update.inner.value);
55	            break;
56	          case RoomListEntriesUpdate_Tags.Set:
57	            rooms[update.inner.index] = update.inner.value;
58	            break;
59	          case RoomListEntriesUpdate_Tags.Remove:
60	            rooms.splice(update.inner.index, 1);
61	            break;
62	          case RoomListEntriesUpdate_Tags.PushFront:
63	            rooms.unshift(update.inner.value);
64	            break;
65	          case RoomListEntriesUpdate_Tags.PushBack:
66	            rooms.push(update.inner.value);
67	            break;
68	          case RoomListEntriesUpdate_Tags.PopFront:
69	            rooms.shift();
70	            break;
71	          case RoomListEntriesUpdate_Tags.PopBack:
72	            rooms.pop();
73	            break;
74	          case RoomListEntriesUpdate_Tags.Truncate:
75	            rooms.splice(update.inner.length);
76	            break;
77	        }
78	      }
79	
80	      roomsRef.current = rooms;
81	
82	      const filtered = rooms.filter((room) => {
83	        const m = room.membership();
84	        return (
85	          m !== Membership.Banned &&
86	          m !== Membership.Left &&
87	          m !== Membership.Knocked
88	        );
89	      });
90	
91	      MatrixJotaiStore.set(MatrixAtoms.roomList, filtered);
92	      return filtered;
93	    };
94	
95	    const updateRoomInfoForDiffs = async (updates: RoomListEntriesUpdate[]) => {
96	      const addedOrUpdated = updates.flatMap((u) => {
97	        switch (u.tag) {
98	          case RoomListEntriesUpdate_Tags.Reset:
99	            return u.inner.values;
100	          case RoomListEntriesUpdate_Tags.Append:
101	            return u.inner.values;
102	          case RoomListEntriesUpdate_Tags.Insert:
103	            return [u.inner.value];
104	          case RoomListEntriesUpdate_Tags.Set:
105	            return [u.inner.value];
106	          case RoomListEntriesUpdate_Tags.PushFront:
107	            return [u.inner.value];
108	          case RoomListEntriesUpdate_Tags.PushBack:
109	            return [u.inner.value];
110	          default:
111	            return [];
112	        }
113	      });
114	
115	      if (addedOrUpdated.length === 0) return;
116	
117	      const currentMap = MatrixJotaiStore.get(MatrixAtoms.roomInfoMap);
118	      const newMap = new Map(currentMap);
119	
120	      await Promise.allSettled(
121	        addedOrUpdated.map(async (room: RoomInterface) => {
122	          try {
123	            const info = await room.roomInfo();
124	            newMap.set(room.id(), info);
125	          } catch {
126	            // ignore per-room failures
127	          }
128	        }),
129	      );
130	
131	      MatrixJotaiStore.set(MatrixAtoms.roomInfoMap, newMap);
132	    };
133	
134	    const init = async () => {
135	      try {
136	        const roomListService = syncService.roomListService();
137	        if (!roomListService) return;
138	
139	        roomListRef.current = await roomListService.allRooms();
140	
141	        // Listener stored at module scope to prevent GC — onUpdate must be synchronous
142	        entriesResultRef.current =
143	          roomListRef.current.entriesWithDynamicAdaptersWith(500, true, {
144	            onUpdate: (updates) => {
145	              // Sync update — no await here
146	              applyDiffsAndPublish(updates);
147	              // Fire-and-forget async room info
148	              updateRoomInfoForDiffs(updates).catch(console.warn);
149	            },
150	          });
151	
152	        streamHandle = entriesResultRef.current.entriesStream();
153	
154	        // State listener — fallback refresh + loading indicator
155	        stateHandle = roomListService.state({
156	          onUpdate: (state: RoomListServiceState) => {
157	            if (
158	              state === RoomListServiceState.SettingUp ||
159	              state === RoomListServiceState.Recovering
160	            ) {
161	              setIsLoading(true);
162	              if (!hasShownInitialSyncToast.current) {
163	                hasShownInitialSyncToast.current = true;
164	                Toast.show({
165	                  type: "info",
166	                  text1: "Syncing rooms...",
167	                  autoHide: false,
168	                });
169	              }
170	            }
171	
172	            if (state === RoomListServiceState.Running) {
173	              // Fallback: refresh from client in case subscription missed any diffs
174	              MatrixCore.refreshRoomList().then(() => {
175	                setIsLoading(false);
176	                Toast.hide();
177	              });
178	            }
179	          },
180	        });
181	      } catch (error) {
182	        console.error("[RoomListProvider] init failed:", error);
183	      } finally {
184	        setIsLoading(false);
185	      }
186	    };
187	
188	    init();
189	
190	    return () => {
191	      streamHandle?.cancel?.();
192	      stateHandle?.cancel?.();
193	      roomsRef.current = [];
194	      roomListRef.current = null;
195	      entriesResultRef.current = null;
196	    };
197	  }, [client, syncService]);
198	
199	  return <></>;
200	};
