await Promise.allSettled(
  addedOrUpdated.map(async (room: RoomInterface) => {
    try {
      const [info, latestEvent] = await Promise.all([
        room.roomInfo(),
        room.latestEvent(),
      ]);
      newMap.set(room.id(), info);
      if (latestEvent?.timestamp !== undefined) {
        lastEventTimestampMap.set(room.id(), latestEvent.timestamp);
      }
    } catch {
      // ignore per-room failures
    }
  }),
);

MatrixJotaiStore.set(MatrixAtoms.roomInfoMap, newMap);

// Re-sort the published room list so rooms with the newest events appear first
const currentRooms = MatrixJotaiStore.get(MatrixAtoms.roomList);
const sorted = [...currentRooms].sort((a, b) => {
  const tsA = lastEventTimestampMap.get(a.id()) ?? 0n;
  const tsB = lastEventTimestampMap.get(b.id()) ?? 0n;
  return tsB > tsA ? 1 : tsB < tsA ? -1 : 0;
});
MatrixJotaiStore.set(MatrixAtoms.roomList, sorted);

