      .then((ns) => ns.getUserDefinedRoomNotificationMode(roomId))
      .then((mode) => {
        if (abortController.signal.aborted) return;
        const muted = mode === RoomNotificationMode.Mute;
        isMutedCache.set(roomId, muted);
        setIsMuted(muted);
      })
      .catch((error) => {
        if (!abortController.signal.aborted) console.error(error);
      });

